code.cpp:
class Solution {
public:
    int twoEggDrop(int n) {
        int lo = 1, hi = n;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if ((long long)mid * (mid + 1) / 2 >= n) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return lo;
    }
};
